import React, { useState } from 'react';
import './Wiki.css';

function Wiki() {
  const [openCategory, setOpenCategory] = useState(null);

  const toggleCategory = (id) => {
    setOpenCategory(openCategory === id ? null : id);
  };

  const wikiData = [
    {
      id: 'quests',
      title: '🗺️ Quests',
      items: [
        'Defeat 10 demons',
        'Collect 5 wisteria flowers',
        'Unlock the Demon Slayer mark',
      ],
    },
    {
      id: 'breathing',
      title: '🌬️ Breathing Styles',
      items: [
        'Water Breathing',
        'Flame Breathing',
        'Thunder Breathing',
        'Beast Breathing',
      ],
    },
  ];

  return (
    <div className="Wiki">
      <h1>📖 HinokamiMC Wiki</h1>

      <div className="wiki-categories">
        {wikiData.map((cat) => (
          <div key={cat.id} className="wiki-category">
            <div
              className="wiki-category-header"
              onClick={() => toggleCategory(cat.id)}
            >
              <h2>{cat.title}</h2>
              <span>{openCategory === cat.id ? '−' : '+'}</span>
            </div>

            {openCategory === cat.id && (
              <ul className="wiki-category-items">
                {cat.items.map((item, idx) => (
                  <li key={idx}>{item}</li>
                ))}
              </ul>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default Wiki;
